// src/SlackConverter.ts
function convertToSlackMarkdown(markdown) {
  const lines = markdown.split("\n");
  const result = [];
  let inCodeBlock = false;
  let codeBlockContent = [];
  for (const line of lines) {
    if (line.trim().startsWith("```")) {
      if (!inCodeBlock) {
        inCodeBlock = true;
        codeBlockContent = [];
        result.push("```");
      } else {
        inCodeBlock = false;
        result.push(...codeBlockContent);
        result.push("```");
      }
      continue;
    }
    if (inCodeBlock) {
      codeBlockContent.push(line);
      continue;
    }
    let processed = line;
    const headingMatch = processed.match(/^(#{1,6})\s+(.+)$/);
    if (headingMatch) {
      processed = `*${headingMatch[2].trim()}*`;
    } else {
      processed = convertInlineFormatting(processed);
    }
    result.push(processed);
  }
  return result.join("\n");
}
function convertInlineFormatting(text) {
  let result = text;
  const codeSpans = [];
  result = result.replace(/`([^`]+)`/g, (_, code) => {
    codeSpans.push(code);
    return `\0CODE${codeSpans.length - 1}\0`;
  });
  result = result.replace(/\*\*\*(.+?)\*\*\*/g, "\0BI_START\0$1\0BI_END\0");
  result = result.replace(/___(.+?)___/g, "\0BI_START\0$1\0BI_END\0");
  result = result.replace(/\*\*(.+?)\*\*/g, "\0B_START\0$1\0B_END\0");
  result = result.replace(/\*([^*\x00]+?)\*/g, "_$1_");
  result = result.replace(/\x00B_START\x00/g, "*");
  result = result.replace(/\x00B_END\x00/g, "*");
  result = result.replace(/\x00BI_START\x00/g, "_*");
  result = result.replace(/\x00BI_END\x00/g, "*_");
  result = result.replace(/~~(.+?)~~/g, "~$1~");
  result = result.replace(/\x00CODE(\d+)\x00/g, (_, idx) => {
    return `\`${codeSpans[parseInt(idx)]}\``;
  });
  return result;
}

// src/NotionConverter.ts
var PLUGIN_TAGS2 = /\s*#(?:todo|todone|idea|ideas|ideation|principle|p[0-4]|focus|future|moved)\b/g;
var CALLOUT_RE = /^(>\s*)\[!(\w+)\]\s*(.*)/;
var WIKI_LINK_ALIAS_RE = /\[\[([^\]|]+)\|([^\]]+)\]\]/g;
var WIKI_LINK_RE = /\[\[([^\]|]+)\]\]/g;
var EMBED_RE = /!\[\[([^\]|]+)(?:\|[^\]]+)?\]\]/g;
function convertToNotionMarkdown(markdown) {
  const lines = markdown.split("\n");
  const result = [];
  let inCodeBlock = false;
  for (const line of lines) {
    if (line.trim().startsWith("```")) {
      inCodeBlock = !inCodeBlock;
      result.push(line);
      continue;
    }
    if (inCodeBlock) {
      result.push(line);
      continue;
    }
    let processed = line;
    const calloutMatch = processed.match(CALLOUT_RE);
    if (calloutMatch) {
      const [, prefix, type, title] = calloutMatch;
      const label = type.charAt(0).toUpperCase() + type.slice(1).toLowerCase();
      processed = title ? `${prefix}**${label}:** ${title}` : `${prefix}**${label}**`;
    }
    processed = processed.replace(EMBED_RE, "");
    processed = processed.replace(WIKI_LINK_ALIAS_RE, "$2");
    processed = processed.replace(WIKI_LINK_RE, "$1");
    processed = processed.replace(PLUGIN_TAGS2, "");
    processed = processed.replace(/\s+$/, "");
    result.push(processed);
  }
  return result.join("\n");
}

// src/SendToProjectModal.ts
var import_obsidian15 = require("obsidian");
var SendToProjectModal = class extends import_obsidian15.Modal {
  constructor(app, suggestedTitle, onSubmit) {
    super(app);
    this.title = suggestedTitle;
    this.onSubmit = onSubmit;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.addClass("warped-todo-send-to-project-modal");
    contentEl.createEl("h2", { text: "Send selection to project" });
    let textEl;
    new import_obsidian15.Setting(contentEl).setName("Title").setDesc("Becomes the heading for this item in the project's TODO.md.").addText((text) => {
      textEl = text.inputEl;
      text.setValue(this.title).onChange((value) => {
        this.title = value;
      });
      text.inputEl.focus();
      text.inputEl.select();
      text.inputEl.addEventListener("keydown", (evt) => {
        if (evt.key === "Enter") {
          evt.preventDefault();
          this.submit();
        }
      });
    });
    new import_obsidian15.Setting(contentEl).addButton(
      (btn) => btn.setButtonText("Send").setCta().onClick(() => this.submit())
    );
  }
  submit() {
    const trimmed = this.title.trim();
    this.close();
    this.onSubmit(trimmed || "Untitled");
  }
  onClose() {
    this.contentEl.empty();
  }
};

